
use std::{borrow::Cow, collections::{HashMap, hash_map::Entry}};

use crate::{captions::ClosedCaptionError, cli::Header};

use super::{TokenKind, parser::{CaptionLexer, CaptionParser}};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ClosedCaptions<'src> {
    pub lang: Cow<'src, str>,
    pub tokens: HashMap<u32, Cow<'src, str>>
}

impl<'src> ClosedCaptions<'src> {
    pub fn parse(source: &'src str) -> Result<Self, ClosedCaptionError> {
        let mut lexer = CaptionLexer::new(&source);
        let toks = lexer.tokenise();

        let mut parser = CaptionParser::new(&toks);
        let mut tokens = HashMap::with_capacity(toks.len());

        parser.expect_literal("lang")?;
        parser.expect_token(TokenKind::OpenBracket)?;

        parser.expect_literal("Language")?;
        let lang = parser.consume_literal()?;

        parser.expect_literal("Tokens")?;
        parser.expect_token(TokenKind::OpenBracket)?;

        while Some(TokenKind::CloseBracket) != parser.peek() {
            let id = parser.consume_literal()?;
            let content = parser.consume_literal()?;

            if id.starts_with("[english]") {
                continue;
            }

            // Account for UTF16 NULL terminator
            if (content.len() + 1) << 1 > Header::BLOCK_SIZE as usize {
                return Err(ClosedCaptionError::CaptionLength { id: id.into() })
            }

            let hash = crc32fast::hash(id.as_bytes());
            match tokens.entry(hash) {
                Entry::Occupied(_) => return Err(ClosedCaptionError::HashCollision { id: id.into() }),
                Entry::Vacant(entry) => entry.insert(content)
            };
        }
        
        parser.expect_token(TokenKind::CloseBracket)?;
        parser.expect_token(TokenKind::CloseBracket)?;

        Ok(Self { lang, tokens })
    }
}

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use crate::captions::parser::CaptionParseError;

    use super::*;

    #[test]
    fn parse_valid() {
        let content = r#""lang"
            {
            "Language"	"russian"
            "Tokens"
            {
            "barn.anotherdropship"	"Ещё один транспортник!"
            "[english]barn.anotherdropship"	"Another dropship! "
            "barn.bunyip"	" "
            "[english]barn.bunyip"	" "
            }
            }
        "#;

        let mut tokens = HashMap::<u32, Cow<str>>::new();
        tokens.insert(3659759262, "Ещё один транспортник!".into());
        tokens.insert(3376503187, " ".into());

        assert_eq!(
            ClosedCaptions::parse(content),
            Ok(ClosedCaptions { lang: "russian".into(), tokens })
        );
    }

    #[test]
    fn parse_invalid_format() {
        let content_missing_tokens = r#""lang"
            {
            "Language"	"russian"
            {
            "barn.anotherdropship"	"Ещё один транспортник!"
            }
            }
        "#;

        assert_eq!(
            ClosedCaptions::parse(content_missing_tokens),
            Err(ClosedCaptionError::Format(
                CaptionParseError::LiteralMismatch { line: 4, expected: "Tokens".into(), found: "{".into() })
            )
        );

        assert_eq!(
            ClosedCaptions::parse(""),
            Err(ClosedCaptionError::Format(
                CaptionParseError::UnexpectedEof { expected: TokenKind::String })
            )
        );
    }

    #[test]
    fn parse_caption_length() {
        let content_exceeds_8192 = r#""lang"
            { 
            "Language" "English" 
            "Tokens" 
            { 
                "barn.anotherdropship"	"Another dropship! "
                "barn.bunyip"	""
                "barn.chatter"	"We're picking up radio chatter. They're looking for your car. "
            } 
            }
        "#;

        let content_equals_8192 = r#"
            "lang"
            { 
            "Language" "English" 
            "Tokens" 
            { 
                "barn.anotherdropship"	"Another dropship! "
                "barn.bunyip"	""
                "barn.chatter"	"We're picking up radio chatter. They're looking for your car. "
            } 
            }
        "#;
        
        assert_eq!(
            ClosedCaptions::parse(content_exceeds_8192),
           Err(ClosedCaptionError::CaptionLength { id: "barn.bunyip".into() })
        );

        assert!(ClosedCaptions::parse(content_equals_8192).is_ok());
    }

    #[test]
    fn parse_hash_collision() {
        let content = r#""lang"
            {
            "Language"	"russian"
            "Tokens"
            {
            "barn.anotherdropship"	"Ещё один транспортник!"
            "[english]barn.anotherdropship"	"Another dropship! "
            "barn.anotherdropship"	" "
            "[english]barn.bunyip"	" "
            }
            }
        "#;

        assert_eq!(
            ClosedCaptions::parse(content),
           Err(ClosedCaptionError::HashCollision { id: "barn.anotherdropship".into() })
        );
    }
}